$('start').onclick=async()=>{if(mode!=='online'){startLocal();return;}try{const v=await api('create',{name:$('player-name').value,expansions:[...extensions]},false);room=v.room;connect({token:v.token,playerId:v.playerId});screen('lobby');renderLobby();}catch(error){toast(error.message);}};
$('join-room').onclick=async()=>{try{const v=await api('join',{name:$('player-name').value,code:$('room-code').value},false);room=v.room;connect({token:v.token,playerId:v.playerId});screen('lobby');renderLobby();}catch(error){toast(error.message);}};
