$('copy-invite').onclick=async()=>{try{await navigator.clipboard.writeText($('invite-url').value);toast('邀请链接已复制，朋友打开后会填好房间码');}catch{$('invite-url').select();document.execCommand('copy');toast('邀请链接已选中，可手动复制');}};
