$('continue-game').onclick=()=>{if(room&&g){screen('game');renderGame();return;}const saved=store.get('carc-game');if(saved?.version===1){disconnect();g=saved;mode=g.players.some(p=>p.kind==='ai')?'ai':'local';endedShown=false;screen('game');receiveGame(null);fitMap();}else toast('没有可恢复的对局。');};
$('home-guide').onclick=()=>showGuide();$('game-guide').onclick=()=>showGuide('controls');$('rotate-left').onclick=()=>rotate(-1);$('rotate-right').onclick=()=>rotate(1);$('zoom-in').onclick=()=>zoom(1.18);$('zoom-out').onclick=()=>zoom(1/1.18);$('fit-map').onclick=fitMap;$('hint').onclick=hint;
