$('flip-lake').onclick=()=>{if(isMyTurn()&&g.phase==='tile'&&g.current?.type==='riverDoubleLake'){lakeFlip=1-lakeFlip;renderPreview();if(hover){hover.check=E.valid(g,previewTile(),hover.x,hover.y,bridge);feedback(hover.check);}}};$('toggle-goods').onclick=()=>{showGoods=!showGoods;$('toggle-goods').classList.toggle('active',showGoods);toast(showGoods?'货物图标与标签已显示':'货物标签已收起，可再次打开');};
